rule.definition:
if(
  or(
    toboolean(property(ri!nomination,"isDirectHire",null))=true,
    toboolean(property(ri!nomination,"isReadyForOnboarding",null))=true
  ),
  #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4586114",
  if(
    toboolean(property(ri!nomination,"isInterviewRequested",null))=true,
    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4578354",
    /*Interview Availability*/
    if(
      and(
        toboolean(property(ri!nomination,"isInterviewAvailabilityRequested",toboolean(null)))=true,
        not(property(ri!nomination,"statusId",tointeger(null)) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458889")
        ),
      #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458889",
      if(
        and(
          toboolean(property(ri!nomination,"isInterviewAvailabilityRequested",toboolean(null)))=true,
          property(ri!nomination,"statusId",tointeger(null)) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458889"
        ),
        #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458895",
        /*Office Visit Availability*/
        if(
          and(
            toboolean(property(ri!nomination,"isOfficeVisitAvailabilityRequested",toboolean(null)))=true,
            not(property(ri!nomination,"statusId",tointeger(null)) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458932")
          ),
          #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458932",
          if(
            and(
              toboolean(property(ri!nomination,"isOfficeVisitAvailabilityRequested",toboolean(null)))=true,
              property(ri!nomination,"statusId",tointeger(null)) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458932"
            ),
            #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4458947",
            if(
              /*HR REVIEW*/
              and(
                toboolean(property(ri!nomination,"isHRReview",null))=true,
                not(property(ri!nomination,"statusId",tointeger(null)) = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4489118")
              ),
              #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4489118",
              if(
                /*INSPECTIONS REVIEW*/
                and(
                  toboolean(property(ri!nomination,"isInspectionsReview",null))=true,
                  not(property(ri!nomination,"statusId",tointeger(null)) = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4494074")
                ),
                #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4494074",
                if(
                  and(
                    toboolean(ri!isUserDPPEditor),
                    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!selectedReviewer)
                  ),
                  #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4183431",
                  #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4577779"
                )
              )
            )
          )
        )
      )
    )
  ) 
),
